1	/**
2	 * Товар каталога.
3	 *
4	 * Запись — три поля, и все три обязательны: без артикула запись не найти, без названия не
5	 * показать на витрине, без цены не продать. Конструктор проверяет то, что типом не
6	 * выразить — пустой артикул и дробные копейки: TypeScript снимается на лету, и в рантайме
7	 * сюда приходит что угодно, в том числе из формы ввода.
8	 */
9	
10	export interface Product {
11	  /** Артикул — идентификатор записи в каталоге. Непустая строка. */
12	  code: string;
13	  /** Название, как оно показывается на витрине. */
14	  title: string;
15	  /** Цена в копейках, целое неотрицательное: рублей с плавающей точкой в каталоге нет. */
16	  priceK: number;
17	}
18	
19	/**
20	 * Собрать запись товара с проверкой полей.
21	 *
22	 * Проверки здесь, а не у потребителя: цена «10.5 копейки» всплыла бы не в каталоге, а в
23	 * сумме заказа — там, где уже непонятно, какая запись её принесла.
24	 */
25	export function product(code: string, title: string, priceK: number): Product {
26	  if (code.trim() === '') {
27	    throw new RangeError('артикул товара пуст');
28	  }
29	  if (!Number.isInteger(priceK) || priceK < 0) {
30	    throw new RangeError(`цена в копейках — целое неотрицательное число, получено ${priceK}`);
31	  }
32	  return { code, title, priceK };
33	}
34

1	/**
2	 * Хранение каталога: JSONL.
3	 *
4	 * Одна запись — одна строка JSON, файл — строки через `\n`. Формат — публичный контракт:
5	 * файлы каталога читают внешние службы (витрина, склад, выгрузка в бухгалтерию), и любое
6	 * изменение имён полей здесь — изменение для них. Поэтому набор и порядок полей в строке
7	 * закреплены явно, а не оставлены на усмотрение того, в каком порядке поля легли в объект:
8	 * diff двух выгрузок обязан показывать изменение данных, а не перестановку ключей.
9	 *
10	 * parse проверяет форму, а не доверяет JSON.parse: файл на диске мог написать кто угодно,
11	 * и «undefined в цене» всплыл бы не здесь, а в сумме заказа.
12	 */
13	
14	import { product } from './product.ts';
15	import type { Product } from './product.ts';
16	
17	/** Одна запись → одна строка JSON без переносов. Порядок полей — как в таблице README. */
18	export function serialize(p: Product): string {
19	  return JSON.stringify({ code: p.code, title: p.title, priceK: p.priceK });
20	}
21	
22	/** Одна строка файла → запись. Всё, что не запись каталога, отвергается с названной причиной. */
23	export function parse(line: string): Product {
24	  let raw: unknown;
25	  try {
26	    raw = JSON.parse(line);
27	  } catch (e) {
28	    throw new SyntaxError(`строка каталога не разбирается как JSON: ${e instanceof Error ? e.message : String(e)}`);
29	  }
30	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
31	    throw new TypeError('строка каталога — не объект');
32	  }
33	  const r = raw as Record<string, unknown>;
34	  const code = r['code'];
35	  const title = r['title'];
36	  const priceK = r['priceK'];
37	  if (typeof code !== 'string') throw new TypeError('в строке каталога нет артикула (code)');
38	  if (typeof title !== 'string') throw new TypeError('в строке каталога нет названия (title)');
39	  if (typeof priceK !== 'number') throw new TypeError('в строке каталога нет цены (priceK)');
40	  // Диапазоны — те же, что у конструктора: правило одно и на ввод, и на чтение с диска.
41	  return product(code, title, priceK);
42	}
43	
44	/** Каталог → текст файла JSONL. Каждая строка завершена `\n`, чтобы файлы склеивались конкатенацией. */
45	export function saveAll(products: readonly Product[]): string {
46	  let text = '';
47	  for (const p of products) text += `${serialize(p)}\n`;
48	  return text;
49	}
50	
51	/** Текст файла JSONL → каталог. Пустые строки (в т.ч. хвостовой перевод строки) записями не считаются. */
52	export function loadAll(text: string): Product[] {
53	  const out: Product[] = [];
54	  for (const line of text.split('\n')) {
55	    if (line.trim() === '') continue;
56	    out.push(parse(line));
57	  }
58	  return out;
59	}
60

1	/**
2	 * Тесты хранения: round-trip записи и файла.
3	 *
4	 * Контракт формата здесь проверяется через round-trip (что записали — то и прочитали), а
5	 * не через сравнение с эталонной строкой: точная строка — предмет таблицы в README, и её
6	 * сверяют внешние службы на своей стороне. Отказы parse проверяются на литералах строк —
7	 * это единственные литералы формата в тестах, и они про то, чего в строке НЕ хватает.
8	 */
9	
10	import { deepStrictEqual, ok, strictEqual, throws } from 'node:assert/strict';
11	import { describe, it } from 'node:test';
12	
13	import { loadAll, parse, product, saveAll, serialize } from '../src/index.ts';
14	
15	const screw = product('A-1', 'Шуруп 4×40', 100);
16	const nut = product('B-2', 'Гайка М4', 250);
17	
18	describe('строка каталога', () => {
19	  it('serialize → parse возвращает ту же запись', () => {
20	    deepStrictEqual(parse(serialize(screw)), screw);
21	  });
22	
23	  it('строка одна: переносов внутри нет', () => {
24	    ok(!serialize(screw).includes('\n'));
25	  });
26	
27	  it('строка без цены или с дробной ценой отвергается', () => {
28	    throws(() => parse('{"code":"A-1","title":"Шуруп 4×40"}'), TypeError);
29	    throws(() => parse('{"code":"A-1","title":"Шуруп 4×40","priceK":10.5}'), RangeError);
30	  });
31	
32	  it('не-JSON и не-объект отвергаются', () => {
33	    throws(() => parse('не json'), SyntaxError);
34	    throws(() => parse('[1,2,3]'), TypeError);
35	  });
36	});
37	
38	describe('файл каталога', () => {
39	  it('saveAll → loadAll возвращает те же записи в том же порядке', () => {
40	    deepStrictEqual(loadAll(saveAll([screw, nut])), [screw, nut]);
41	  });
42	
43	  it('каждая строка файла завершена переводом строки', () => {
44	    strictEqual(saveAll([screw]).endsWith('\n'), true);
45	  });
46	
47	  it('пустые строки и хвостовой перевод строки записями не считаются', () => {
48	    const text = `${saveAll([screw])}\n\n${serialize(nut)}\n`;
49	    deepStrictEqual(loadAll(text), [screw, nut]);
50	  });
51	
52	  it('пустой файл — пустой каталог', () => {
53	    deepStrictEqual(loadAll(''), []);
54	  });
55	});
56

